#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: longform-pipeline setup wizard.
# Writes only under ~/.config/longform-pipeline and ~/Library/LaunchAgents,
# plus the iCloud inbox folder the profile names and the launchd log folder.
# Usage:
#   setup.sh                    run the 12-stage wizard
#   setup.sh launchd-install    (re)install the LaunchAgent for every profile
#   setup.sh launchd-uninstall  remove the LaunchAgent
#   setup.sh fixture [path]     generate the 30-second ffmpeg fixture
# ──────────────────────────────────────────────────────────────────────────

CONFIG_ROOT="${LONGFORM_CONFIG_DIR:-$HOME/.config/longform-pipeline}"
PROFILES_DIR="$CONFIG_ROOT/profiles"
ENV_FILE="$CONFIG_ROOT/env"
LOG_DIR="${LONGFORM_LOG_DIR:-$HOME/Library/Logs/longform-pipeline}"
ICLOUD_ROOT="$HOME/Library/Mobile Documents/iCloud~is~workflow~my~workflows/Documents/longform-inbox"
AGENT_LABEL="com.$(id -un).longform-watch"
AGENT_PLIST="$HOME/Library/LaunchAgents/$AGENT_LABEL.plist"
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PLUGIN_ROOT="${CLAUDE_PLUGIN_ROOT:-$(cd "$SCRIPT_DIR/.." && pwd)}"
PLIST_TMPL="$PLUGIN_ROOT/launchd/com.USER.longform-watch.plist.tmpl"
REPO_DOCS="$(cd "$PLUGIN_ROOT/../.." 2>/dev/null && pwd)/docs"

# find_bin prints the longform binary path, or fails.
find_bin() {
  local c
  for c in "${LONGFORM_BIN:-}" "$PLUGIN_ROOT/scripts/longform" "$(command -v longform 2>/dev/null || true)"; do
    [[ -n "$c" && -x "$c" ]] && { printf '%s' "$c"; return 0; }
  done
  return 1
}

# ask_default KEY "Prompt" "default" reads a visible value with a default.
ask_default() {
  local key="$1" prompt="$2" def="$3" input s=$'\001' e=$'\002' p
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$def" ]] && p+="$s$DIM${e}[$def]$s$RESET$e "
  read -e -r -p "$p" input || true
  [[ -z "$input" ]] && input="$def"
  printf -v "$key" '%s' "$input"
}

# pdefault JQPATH FALLBACK prints the existing profile's value or the fallback.
pdefault() {
  local v=""
  if [[ -n "${PROFILE_FILE:-}" && -f "$PROFILE_FILE" ]]; then
    v=$(jq -r "$1 // empty" "$PROFILE_FILE" 2>/dev/null || true)
  fi
  printf '%s' "${v:-$2}"
}

# load_env sources the env file so longform subcommands see OPUSCLIP_API_KEY.
load_env() {
  [[ -f "$ENV_FILE" ]] || return 0
  set -a
  # shellcheck disable=SC1090
  . "$ENV_FILE"
  set +a
}

# make_fixture PATH renders the 30-second test video (see fixtures/README.md).
make_fixture() {
  local out="$1"
  command -v ffmpeg >/dev/null 2>&1 || { warn "ffmpeg missing (brew install ffmpeg)"; return 1; }
  mkdir -p "$(dirname "$out")"
  ffmpeg -y -loglevel error \
    -f lavfi -i "testsrc2=size=1080x1920:rate=30:duration=30" \
    -f lavfi -i "sine=frequency=440:sample_rate=48000:duration=30" \
    -c:v libx264 -pix_fmt yuv420p -preset veryfast -crf 23 \
    -c:a aac -b:a 96k -shortest -movflags +faststart "$out"
  printf '  %s✓ wrote%s %s\n' "$GREEN" "$RESET" "$out"
}

# find_claude prints the claude executable the LaunchAgent should run: the
# one on this shell's PATH (an alias such as claude-secondary resolves to the
# same binary), else the standard install location, else nothing.
find_claude() {
  local c
  c=$(command -v claude 2>/dev/null || true)
  [[ -n "$c" && -x "$c" ]] && { printf '%s' "$c"; return 0; }
  [[ -x "$HOME/.local/bin/claude" ]] && { printf '%s' "$HOME/.local/bin/claude"; return 0; }
  return 0
}

# render_plist writes the LaunchAgent plist from the template with one
# WatchPaths entry per profile inbox.
render_plist() {
  local bin="$1" f inbox tmp
  [[ -f "$PLIST_TMPL" ]] || { warn "template missing: $PLIST_TMPL"; return 1; }
  tmp=$(mktemp)
  for f in "$PROFILES_DIR"/*.json; do
    [[ -f "$f" ]] || continue
    inbox=$(jq -r '.inbox // empty' "$f")
    [[ -z "$inbox" ]] && continue
    inbox="${inbox/#\~/$HOME}"
    printf '    <string>%s</string>\n' "${inbox//&/&amp;}" >> "$tmp"
  done
  mkdir -p "$(dirname "$AGENT_PLIST")" "$LOG_DIR"
  sed -e "s|@@USER@@|$(id -un)|g" \
      -e "s|@@BIN@@|$bin|g" \
      -e "s|@@LOG@@|$LOG_DIR|g" \
      -e "s|@@ENV_FILE@@|$ENV_FILE|g" \
      "$PLIST_TMPL" \
  | awk -v f="$tmp" -v cfg="${CLAUDE_CONFIG_DIR:-}" -v claudebin="$(find_claude)" '
      $0 ~ /^[[:space:]]*@@WATCHPATHS@@[[:space:]]*$/ { while ((getline l < f) > 0) print l; close(f); next }
      $0 ~ /^[[:space:]]*@@CLAUDE_CONFIG@@[[:space:]]*$/ {
        # The headless editorial session must use the same Claude config the
        # wizard ran under (plugin, MCP entry and sign-in all live there).
        if (cfg != "") { print "    <key>CLAUDE_CONFIG_DIR</key>"; print "    <string>" cfg "</string>" }
        next
      }
      $0 ~ /^[[:space:]]*@@CLAUDE_BIN@@[[:space:]]*$/ {
        # launchd loads no shell aliases or user PATH, so name the executable.
        if (claudebin != "") { print "    <key>LONGFORM_CLAUDE</key>"; print "    <string>" claudebin "</string>" }
        next
      }
      { print }' \
  > "$AGENT_PLIST"
  rm -f "$tmp"
  printf '  %s✓ wrote%s %s\n' "$GREEN" "$RESET" "$AGENT_PLIST"
}

launchd_install() {
  local bin
  bin=$(find_bin) || { warn "longform binary not found; run 'make install' first"; return 1; }
  render_plist "$bin" || return 1
  launchctl bootout "gui/$(id -u)/$AGENT_LABEL" >/dev/null 2>&1 || true
  launchctl bootstrap "gui/$(id -u)" "$AGENT_PLIST"
  launchctl kickstart -k "gui/$(id -u)/$AGENT_LABEL" >/dev/null 2>&1 || true
  printf '  %s✓ loaded%s %s\n' "$GREEN" "$RESET" "$AGENT_LABEL"
}

launchd_uninstall() {
  launchctl bootout "gui/$(id -u)/$AGENT_LABEL" >/dev/null 2>&1 || true
  rm -f "$AGENT_PLIST"
  printf '  %s✓ removed%s %s\n' "$GREEN" "$RESET" "$AGENT_LABEL"
}

print_shortcut_recipe() {
  if [[ -f "$REPO_DOCS/shortcut-recipe.md" ]]; then
    # The recipe names the profile, the brand and (when set) the album; | keeps
    # a / in a brand name from ending the sed expression.
    sed -e 's|<profile>|'"$PROFILE"'|g' -e 's|<Brand>|'"${BRAND_DISPLAY:-$PROFILE}"'|g' \
        -e 's|<album>|'"${PHOTOS_ALBUM:-<album>}"'|g' "$REPO_DOCS/shortcut-recipe.md"
    return
  fi
  say "On the iPhone, open Shortcuts and create a new Shortcut named 'Send to $BRAND_DISPLAY inbox':"
  step "Shortcut details: enable 'Show in Share Sheet'; Share Sheet Types = Media only."
  step "Action 1: 'Receive Video input from Share Sheet' (If there's no input: Continue)."
  step "Action 2: 'Save File' with input = Shortcut Input."
  step "  Service: iCloud Drive. Turn OFF 'Ask Where to Save'."
  step "  Destination Path: longform-inbox/$PROFILE   (leave Subpath blank)."
  step "  Turn ON 'Overwrite If File Exists'."
  step "Action 3: 'Show Notification' with text 'Sent to $PROFILE inbox'."
  step "Record a video, tap Share, pick the Shortcut. It lands in the inbox and the Mac picks it up."
}

# fda_steps tells the person how to give the binary launchd runs Full Disk
# Access: osxphotos reads the Photos library database, which macOS guards.
fda_steps() {
  step "System Settings → Privacy & Security → Full Disk Access → + → press Cmd-Shift-G,"
  step "  paste this path, click Open, and make sure its switch is on:"
  note "    $BIN"
  note "Check the grant again after 'make install' or a plugin update replaces that file."
}

# photos_access_check reads the profile's album once with the longform binary
# (dry run: nothing staged, downloaded or notified) and says what is missing.
photos_access_check() {
  local rc=0
  say "Reading the Photos album '$PHOTOS_ALBUM' once (dry run; can take a minute on a big library):"
  # Run from the log folder: osxphotos drops osxphotos_crash.log in its cwd.
  (cd "$LOG_DIR" && "$BIN" photos-watch --profile "$PROFILE" --dry-run) 2>&1 | sed 's/^/    /' || rc=$?
  case $rc in
    0)
      printf '  %s✓ read%s the album %s from this terminal\n' "$GREEN" "$RESET" "$PHOTOS_ALBUM"
      say "launchd runs the binary without this terminal's permissions, so it needs its"
      say "own Full Disk Access grant, once:"
      fda_steps
      open_url "x-apple.systempreferences:com.apple.preference.security?Privacy_AllFiles"
      ;;
    69)
      if [[ -z "${OSXPHOTOS:-}" ]]; then
        warn "osxphotos is not installed: pipx install osxphotos (or brew install osxphotos), then re-run the wizard"
      else
        warn "osxphotos could not read the Photos library (message above)."
        [[ -f "$LOG_DIR/osxphotos_crash.log" ]] && note "osxphotos details: $LOG_DIR/osxphotos_crash.log"
        say "Grant Full Disk Access to the binary launchd runs (and to this terminal app"
        say "if you want the check to pass from here too):"
        fda_steps
        open_url "x-apple.systempreferences:com.apple.preference.security?Privacy_AllFiles"
        SKIPPED+=("Full Disk Access for $BIN, then check: $BIN photos-watch --profile $PROFILE --dry-run")
      fi
      ;;
    *)
      warn "longform photos-watch --dry-run exited $rc (message above)"
      SKIPPED+=("Photos album check: $BIN photos-watch --profile $PROFILE --dry-run (exited $rc)")
      ;;
  esac
  note "On this Mac: Photos → Settings → iCloud → 'Download Originals to this Mac', so each"
  note "recording's full file arrives on its own; until it does the watcher waits and notifies once."
}

# expand_tilde PATH prints PATH with a leading ~ replaced by $HOME (for
# checks only; the profile keeps what the person typed, the binary expands ~).
expand_tilde() { printf '%s' "${1/#\~/$HOME}"; }

# csv_items "a, b,,c" sets the array CSV_ITEMS to the trimmed, non-empty items.
csv_items() {
  local raw item
  CSV_ITEMS=()
  IFS=',' read -r -a raw <<<"$1"
  for item in ${raw[@]+"${raw[@]}"}; do
    item="${item#"${item%%[![:space:]]*}"}"; item="${item%"${item##*[![:space:]]}"}"
    [[ -n "$item" ]] && CSV_ITEMS+=("$item")
  done
  return 0
}

# EVC brand palette, offered as the custom-html default.
EVC_PALETTE="navy=#14386B,green=#2D8A3E,yellow=#F2B705,cream=#F5ECD7"

# ask_statics asks how image posts are made (statics.engine and what that
# engine needs), whether static captions end with the newsletter CTA, and the
# Buffer format tag per format. Every default is the existing profile's value.
# Sets STATICS_ENGINE, STATICS_FORMATS, TEMPLATES_DIR, CAROUSEL_DIR,
# BRAND_TOKENS (JSON), REFERENCE_DIR, STATIC_CTA, CTA_SCRIPT, FORMAT_TAGS (JSON).
# ~ in path defaults is kept literal on purpose: the binary expands it.
# shellcheck disable=SC2088
ask_statics() {
  local def f tag p ok csv
  say "Statics: image posts through Buffer. Engines (docs/profile-schema.md):"
  note "  templates            fill your Claude Design templates (default)"
  note "  newsletter-carousel  the EVC newsletter carousel system (10 illustrated slides, quote card)"
  note "  custom-html          the editorial session designs each post's HTML from brand tokens"
  while :; do
    ask_default STATICS_ENGINE "Statics engine:" "$(pdefault .statics.engine templates)"
    case "$STATICS_ENGINE" in templates|newsletter-carousel|custom-html) break ;; esac
    warn "templates, newsletter-carousel or custom-html"
  done
  # Formats default to the existing list only when the engine is unchanged.
  if [[ "$(pdefault .statics.engine templates)" == "$STATICS_ENGINE" ]]; then
    csv="$(pdefault '.statics.formats | join(",")' "")"
  else
    csv=""
  fi
  TEMPLATES_DIR="$(pdefault .statics.templates_dir "$PROFILES_DIR/$PROFILE/templates")"
  CAROUSEL_DIR="$(pdefault .statics.carousel_dir "")"
  REFERENCE_DIR="$(pdefault .statics.reference_dir "")"
  BRAND_TOKENS='{}'

  case "$STATICS_ENGINE" in
    templates)
      while :; do
        ask_default STATICS_FORMATS "Formats, comma-separated (quote, carousel, still, frame_carousel):" "${csv:-quote,carousel,still,frame_carousel}"
        ok=1
        csv_items "$STATICS_FORMATS"
        for f in ${CSV_ITEMS[@]+"${CSV_ITEMS[@]}"}; do
          case "$f" in quote|carousel|still|frame_carousel) ;; *) warn "$f is not a templates format"; ok=0 ;; esac
        done
        (( ${#CSV_ITEMS[@]} )) || ok=0
        (( ok )) && break
      done
      ;;
    newsletter-carousel)
      def="$CAROUSEL_DIR"
      [[ -z "$def" && -d "$HOME/dev/claude-social-media-skills/carousel-newsletter" ]] && def="~/dev/claude-social-media-skills/carousel-newsletter"
      while :; do
        ask_default CAROUSEL_DIR "carousel-newsletter folder (claude-social-media-skills/carousel-newsletter):" "$def"
        p="$(expand_tilde "$CAROUSEL_DIR")"
        if [[ -n "$CAROUSEL_DIR" && -f "$p/templates/render.sh" && -f "$p/templates/gen_illustration.py" ]]; then
          printf '  %s✓ found%s templates/render.sh and templates/gen_illustration.py\n' "$GREEN" "$RESET"
          break
        fi
        if [[ -z "$CAROUSEL_DIR" ]]; then warn "required for newsletter-carousel"; continue; fi
        warn "$p has no templates/render.sh or templates/gen_illustration.py"
        if confirm "Keep it anyway (fix the folder before the first image post)?"; then
          SKIPPED+=("statics.carousel_dir $p needs templates/render.sh and templates/gen_illustration.py")
          break
        fi
      done
      while :; do
        ask_default STATICS_FORMATS "Formats, comma-separated (carousel, quote):" "${csv:-carousel,quote}"
        ok=1
        csv_items "$STATICS_FORMATS"
        for f in ${CSV_ITEMS[@]+"${CSV_ITEMS[@]}"}; do
          [[ "$f" == carousel || "$f" == quote ]] || { warn "$f is not a newsletter-carousel format"; ok=0; }
        done
        (( ${#CSV_ITEMS[@]} )) || ok=0
        (( ok )) && break
      done
      ;;
    custom-html)
      say "Brand tokens the posts are designed from."
      while :; do
        ask_default BRAND_PALETTE "Palette, name=colour comma-separated (EVC: $EVC_PALETTE):" \
          "$(pdefault '.brand.palette | to_entries | map("\(.key)=\(.value)") | join(",")' "$EVC_PALETTE")"
        ok=1
        csv_items "$BRAND_PALETTE"
        for f in ${CSV_ITEMS[@]+"${CSV_ITEMS[@]}"}; do
          [[ "$f" =~ ^[A-Za-z0-9_-]+[[:space:]]*=[[:space:]]*[^=[:space:]][^=]*$ ]] || { warn "not name=colour: $f"; ok=0; }
        done
        (( ${#CSV_ITEMS[@]} )) || { warn "at least one colour"; ok=0; }
        (( ok )) && break
      done
      ask_default BRAND_FONTS "Font stacks, separated by | (first is the display face):" \
        "$(pdefault '.brand.fonts | join(" | ")' "Inter, 'Helvetica Neue', sans-serif")"
      ask_default BRAND_LOGO "Logo (wordmark) text:" "$(pdefault .brand.logo_text "$BRAND_DISPLAY")"
      BRAND_TOKENS=$(jq -cn --arg pal "$BRAND_PALETTE" --arg fonts "$BRAND_FONTS" --arg logo "$BRAND_LOGO" '{
        palette: ($pal | split(",") | map(gsub("^\\s+|\\s+$";"")) | map(select(length > 0) | split("=") | {key: (.[0] | gsub("^\\s+|\\s+$";"")), value: (.[1:] | join("=") | gsub("^\\s+|\\s+$";""))}) | from_entries),
        fonts: ($fonts | split("|") | map(gsub("^\\s+|\\s+$";"")) | map(select(length > 0)))
      } + (if $logo == "" then {} else { logo_text: $logo } end)')
      def="$REFERENCE_DIR"
      [[ -z "$def" && -d "$PROFILES_DIR/$PROFILE/designs" ]] && def="$PROFILES_DIR/$PROFILE/designs"
      note "Reference designs: a folder with README.md (design principles) and one subfolder per approved design."
      [[ -n "$def" ]] && note "type - for none"
      while :; do
        ask_default REFERENCE_DIR "Reference designs folder (blank = none):" "$def"
        [[ "$REFERENCE_DIR" == "-" ]] && REFERENCE_DIR=""
        [[ -z "$REFERENCE_DIR" ]] && break
        p="$(expand_tilde "$REFERENCE_DIR")"
        if [[ -d "$p" ]]; then
          [[ -f "$p/README.md" ]] || warn "no README.md in $p; the skill reads the design principles from it"
          break
        fi
        warn "not a folder: $p (the profile would not load)"
      done
      while :; do
        ask_default STATICS_FORMATS "Format names, comma-separated (e.g. six_stops,before_after):" "${csv:-carousel}"
        ok=1
        csv_items "$STATICS_FORMATS"
        for f in ${CSV_ITEMS[@]+"${CSV_ITEMS[@]}"}; do
          [[ "$f" =~ ^[A-Za-z0-9_-]+$ ]] || { warn "letters, digits, _ and - only: $f"; ok=0; }
        done
        (( ${#CSV_ITEMS[@]} )) || ok=0
        (( ok )) && break
      done
      ;;
  esac

  # Newsletter canonical CTA on every static caption.
  if [[ "$(pdefault .cta.static_cta "")" == newsletter-canon ]]; then def=yes; else def=no; fi
  ask_default STATIC_CTA_YN "End every static caption with the newsletter canonical CTA (yes/no):" "$def"
  STATIC_CTA=""
  CTA_SCRIPT="$(pdefault .cta.cta_script "")"
  if [[ "$STATIC_CTA_YN" =~ ^[Yy] ]]; then
    STATIC_CTA=newsletter-canon
    while :; do
      ask_default CTA_SCRIPT "CTA script (claude-social-media-skills/_shared/cta.sh):" "${CTA_SCRIPT:-~/dev/claude-social-media-skills/_shared/cta.sh}"
      p="$(expand_tilde "$CTA_SCRIPT")"
      if [[ -f "$p" && -x "$p" ]]; then
        printf '  %s✓ found%s %s (executable)\n' "$GREEN" "$RESET" "$p"
        break
      fi
      warn "not an executable file: $p"
      if [[ -n "$CTA_SCRIPT" ]] && confirm "Keep it anyway (fix it before the first image post)?"; then
        SKIPPED+=("cta.cta_script $p must be an executable file")
        break
      fi
    done
    # The newest newsletter title comes from the voice corpus; the profile does
    # not load without it.
    while [[ -z "$VOICE_CORPUS" ]]; do
      warn "the newsletter CTA needs copy.voice_corpus (the newest newsletter title comes from it)"
      ask_default VOICE_CORPUS "Voice corpus path:" "$CONFIG_ROOT/voice/$PROFILE.json"
    done
    p="$(expand_tilde "$VOICE_CORPUS")"
    if [[ -f "$p" ]]; then
      printf '  %s✓ found%s copy.voice_corpus %s\n' "$GREEN" "$RESET" "$p"
    else
      warn "copy.voice_corpus $p does not exist yet; build it before the first image post"
      SKIPPED+=("copy.voice_corpus $p (needed by cta.static_cta newsletter-canon)")
    fi
  fi

  # Buffer format tags: the newsletter skills' format-tag keys, per format.
  # The templates engine uses buffer.tags (stage 7) unless the brand shares the
  # newsletter process and takes these instead.
  FORMAT_TAGS='{}'
  ok=1
  if [[ "$STATICS_ENGINE" == templates ]]; then
    if [[ -n "$(pdefault '.buffer.format_tags | length | select(. > 0)' "")" ]]; then def=yes; else def=no; fi
    ask_default FTAGS_YN "Tag statics with the newsletter skills' format tags instead of the stage 7 tags (yes/no):" "$def"
    [[ "$FTAGS_YN" =~ ^[Yy] ]] || ok=0
  fi
  if (( ok )); then
    say "Buffer format tag per format: 'carousel' for a multi-image post, 'verbatim_quote'"
    say "for a single card showing a verbatim transcript quote, blank = untagged (the skill"
    say "then raises it as a decision instead of mislabelling it)."
    csv_items "$STATICS_FORMATS"
    for f in ${CSV_ITEMS[@]+"${CSV_ITEMS[@]}"}; do
      case "$f" in carousel) def=carousel ;; quote) def=verbatim_quote ;; *) def="" ;; esac
      while :; do
        ask_default tag "  format tag for $f (carousel, verbatim_quote, blank = none):" \
          "$(pdefault ".buffer.format_tags[\"$f\"]" "$def")"
        case "$tag" in ""|carousel|verbatim_quote) break ;; esac
        warn "carousel, verbatim_quote or blank"
      done
      if [[ -n "$tag" ]]; then
        FORMAT_TAGS=$(jq -c --arg k "$f" --arg v "$tag" '. + {($k): $v}' <<<"$FORMAT_TAGS")
      fi
    done
  fi
}

run_wizard() {

TOTAL_STAGES=12
mkdir -p "$PROFILES_DIR"

banner "longform-pipeline setup"

for dep in jq ffmpeg; do
  command -v "$dep" >/dev/null 2>&1 || { warn "$dep is required (brew install $dep)"; exit 1; }
done

# ── 1 ──────────────────────────────────────────────────────────────────────
stage "Profile name and brand"
say "One profile per brand. The name is a slug used for folders and filenames."
while :; do
  ask_default PROFILE "Profile name (e.g. evc, sandbox-bjj):" "${PROFILE:-evc}"
  [[ "$PROFILE" =~ ^[a-z0-9][a-z0-9-]{0,31}$ ]] && break
  warn "lowercase letters, digits and dashes only"
done
PROFILE_FILE="$PROFILES_DIR/$PROFILE.json"
[[ -f "$PROFILE_FILE" ]] && note "profile exists; Enter keeps each current value"
ask_default BRAND_DISPLAY "Brand display name:" "$(pdefault .brand.display "")"
ask_default BRAND_SITE "Brand site URL:" "$(pdefault .brand.site "")"
ask_default ORIENTATION "Orientation, portrait or landscape:" "$(pdefault .orientation portrait)"
[[ "$ORIENTATION" == landscape ]] || ORIENTATION=portrait
if [[ "$ORIENTATION" == landscape ]]; then STITCH_DEF=true; else STITCH_DEF=false; fi
ask_default STITCH "Stitch several files into one segment (true/false):" "$(pdefault .stitch.enabled "$STITCH_DEF")"
[[ "$STITCH" == true ]] || STITCH=false
ask_default STITCH_WINDOW "Stitch session window, minutes:" "$(pdefault .stitch.session_window_min 90)"

# ── 2 ──────────────────────────────────────────────────────────────────────
stage "Inbox folder"
INBOX="$ICLOUD_ROOT/$PROFILE"
say "The iPhone Shortcut saves into this iCloud Drive folder; the watcher reads it:"
note "$INBOX"
mkdir -p "$INBOX"
printf '  %s✓ created%s %s\n' "$GREEN" "$RESET" "$INBOX"
pause

# ── 3 ──────────────────────────────────────────────────────────────────────
stage "OpusClip API key"
say "The watcher runs under launchd, so it needs a key (Pro or Enterprise plan)."
open_url "https://clip.opus.pro/dashboard"
step "Dashboard → Settings → API → copy the key."
ask_secret OPUSCLIP_API_KEY "Paste OPUSCLIP_API_KEY (hidden):"
write_env OPUSCLIP_API_KEY "$OPUSCLIP_API_KEY"
note "stored in $ENV_FILE (mode 0600); the LaunchAgent sources it via LONGFORM_ENV_FILE"

# ── 4 ──────────────────────────────────────────────────────────────────────
stage "OpusClip MCP (interactive sessions)"
say "Interactive sessions use the OpusClip MCP over OAuth; launchd uses the key."
note "The MCP entry is written to the Claude config this wizard runs under"
note "(CLAUDE_CONFIG_DIR if set, else ~/.claude); the LaunchAgent is pinned to the"
note "same config, so headless sessions find the plugin, the MCP and the sign-in there."
if [[ -n "${CLAUDE_CONFIG_DIR:-}" ]]; then
  note "CLAUDE_CONFIG_DIR=$CLAUDE_CONFIG_DIR (the Claude desktop app's shell sets this)"
else
  note "CLAUDE_CONFIG_DIR is not set: using ~/.claude (the terminal CLI)"
fi
say "The OpusClip connector attached to your claude.ai account is the preferred route:"
say "it follows the account, so every session signed in as you sees it, and its post and"
say "schedule tools hand back a confirmation link instead of committing directly."
if command -v claude >/dev/null 2>&1 && claude mcp list 2>/dev/null | grep -qi 'claude.ai OpusClip'; then
  printf '  %s✓ found%s the claude.ai OpusClip connector in this config\n' "$GREEN" "$RESET"
else
  step "Add it once: in a Claude session run '/mcp' and connect OpusClip, or add OpusClip under claude.ai → Settings → Connectors, then sign in on OpusClip's consent page."
  SKIPPED+=("connect the claude.ai OpusClip connector (/mcp or claude.ai → Settings → Connectors)")
fi
note "The launchd watcher never uses the connector: its uploads go through the REST API with the key from stage 3."
pause "OpusClip connected (or skipping for now)?"

# ── 5 ──────────────────────────────────────────────────────────────────────
stage "Connect social accounts in the OpusClip dashboard"
say "OpusClip can only schedule to accounts connected in its dashboard. TikTok and X"
say "were not connected when this plugin was probed; the skill skips any platform"
say "without an account id, so connect everything you want posts on before stage 6."
open_url "https://clip.opus.pro/dashboard/social"
step "Connect: YouTube, Instagram, Facebook page, LinkedIn page and profile, TikTok, and X if you use it."
step "Reconnect anything marked expired; a token that expires later shows up as a failed schedule."
pause "Every platform you want is connected?"

# ── 6 ──────────────────────────────────────────────────────────────────────
stage "OpusClip social accounts"
say "Each platform cell schedules against an OpusClip postAccountId."
load_env
if BIN=$(find_bin); then
  "$BIN" opus accounts 2>&1 | sed 's/^/    /' || warn "longform opus accounts failed; paste ids by hand"
else
  warn "longform binary not found (make install); paste ids from the dashboard"
  open_url "https://clip.opus.pro/dashboard/social"
fi
for k in youtube instagram facebook linkedin_page linkedin_profile tiktok; do
  ask_default "ACCT_$k" "postAccountId for $k (blank = not connected):" "$(pdefault ".opusclip.accounts.$k" "")"
done
say "Facebook and LinkedIn share one postAccountId across pages and profiles, so those"
say "cells also need the subAccountId shown above (Instagram has one too)."
for k in instagram facebook linkedin_page linkedin_profile; do
  ask_default "SUB_$k" "subAccountId for $k (blank = none):" "$(pdefault ".opusclip.sub_accounts.$k" "")"
done
note "Template ids: the account's only template when probed was 665fefb18ce49592eaeff8a0 ('Preset template 1': portrait, captions on, no overlay)."
ask_default TEMPLATE_ID "OpusClip brand template id:" "$(pdefault .opusclip.template_id 665fefb18ce49592eaeff8a0)"
ask_default STRIP_OVERLAY "Strip the account-default overlay after render (true/false):" "$(pdefault .opusclip.strip_overlay true)"
[[ "$STRIP_OVERLAY" == false ]] || STRIP_OVERLAY=true
ask_default SHORTS_MODEL "Shorts curation model, ClipBasic or ClipAnything:" "$(pdefault .opusclip.shorts.model ClipBasic)"
[[ "$SHORTS_MODEL" == ClipAnything ]] || SHORTS_MODEL=ClipBasic
SHORTS_PROMPT=""
if [[ "$SHORTS_MODEL" == ClipAnything ]]; then
  ask_default SHORTS_PROMPT "ClipAnything prompt:" "$(pdefault .opusclip.shorts.prompt "complete technique demonstrations and the single key detail the instructor emphasizes")"
fi
ask_default REMOVE_FILLER "Remove filler words in shorts (true/false):" "$(pdefault .opusclip.shorts.remove_filler true)"
[[ "$REMOVE_FILLER" == false ]] || REMOVE_FILLER=true

# ── 7 ──────────────────────────────────────────────────────────────────────
stage "Buffer tags and channels"
say "Statics post through Buffer with one format tag each so /flywheel can measure them."
note "These four tags serve the templates engine. newsletter-carousel and custom-html use"
note "the newsletter skills' format tags instead (asked in stage 10); leave these blank then."
open_url "https://publish.buffer.com"
step "Settings → Tags → create these four (exact names):"
for t in format:video-quote format:video-carousel format:video-still format:video-frame-carousel; do note "  $t"; done
step "Open each tag; its id is the last path segment of the URL (or ask the Buffer MCP: list tags)."
for t in video_quote video_carousel video_still video_frame_carousel; do
  ask_default "BTAG_$t" "Tag id for format:${t//_/-}:" "$(pdefault ".buffer.tags.$t" "")"
done
step "Channel ids: Buffer MCP 'list channels', or the id in each channel's URL."
for c in instagram linkedin facebook threads; do
  ask_default "BCHAN_$c" "Buffer channel id for $c (blank = skip):" "$(pdefault ".buffer.channels.$c" "")"
done

# ── 8 ──────────────────────────────────────────────────────────────────────
stage "Slack notifications (optional)"
say "The brief is mirrored to Slack when a webhook is set; macOS notifications always fire."
if confirm "Configure a Slack incoming webhook?"; then
  open_url "https://api.slack.com/apps"
  step "Your app → Incoming Webhooks → Add New Webhook to Workspace → pick the channel → copy the URL."
  ask_secret SLACK_WEBHOOK_URL "Paste the webhook URL (hidden):"
  write_env SLACK_WEBHOOK_URL "$SLACK_WEBHOOK_URL"
  ask_default SLACK_CHANNEL "Slack channel id (for the brief link):" "$(pdefault .notify.slack_channel "")"
else
  SLACK_CHANNEL="$(pdefault .notify.slack_channel "")"
  note "skipped; re-run the wizard later to add it"
fi

# ── 9 ──────────────────────────────────────────────────────────────────────
stage "iPhone Shortcut"
say "Two feeds carry a recording from the phone to this Mac:"
step "a Photos album: one tap ('Mark for $BRAND_DISPLAY') adds the recording to the album and"
say "  iCloud Photos syncs the bytes in the background (nothing is copied on the phone);"
step "the iCloud Drive inbox: 'Send to $BRAND_DISPLAY inbox' copies the file (always built, the fallback)."
PHOTOS_ALBUM_PREV="$(pdefault .photos.album "")"
[[ -n "$PHOTOS_ALBUM_PREV" ]] && note "type - to turn the album feed off"
ask_default PHOTOS_ALBUM "Photos album the phone tags recordings into (blank = iCloud Drive inbox only):" "$PHOTOS_ALBUM_PREV"
[[ "$PHOTOS_ALBUM" == "-" ]] && PHOTOS_ALBUM=""
# Kept from the existing profile (hand-edited only; see docs/profile-schema.md).
PHOTOS_DL_MISSING="$(pdefault .photos.download_missing false)"
[[ "$PHOTOS_DL_MISSING" == true ]] || PHOTOS_DL_MISSING=false
PHOTOS_LIBRARY="$(pdefault .photos.library "")"
# ls only tests two fixed install paths (pipx, Homebrew); nothing is parsed.
# shellcheck disable=SC2012
OSXPHOTOS=$(command -v osxphotos || ls "$HOME/.local/bin/osxphotos" /opt/homebrew/bin/osxphotos 2>/dev/null | head -1 || true)
if [[ -n "$PHOTOS_ALBUM" ]]; then
  # One pause when the album is set, whatever this Mac has installed, so the
  # prompt count depends only on the answers (and the two Shortcuts import
  # dialogs never stack).
  if [[ -n "$OSXPHOTOS" ]]; then
    note "osxphotos: $OSXPHOTOS (the watcher reads the album with it)"
  else
    warn "osxphotos not found; the watcher needs it to read the album: pipx install osxphotos (or brew install osxphotos)"
    SKIPPED+=("install osxphotos for the Photos album feed: pipx install osxphotos (or brew install osxphotos), then re-run the wizard")
  fi
  step "On the iPhone: Photos → Albums → + → New Album, named exactly: $PHOTOS_ALBUM   (skip if it exists)."
  [[ "$STITCH" == true ]] && note "stitching: add all of a class's clips to the album; the Mac waits until every one has synced, then stitches them into one job"
  if BIN=$(find_bin) && command -v shortcuts >/dev/null 2>&1; then
    if "$BIN" shortcut --profile "$PROFILE" --brand "$BRAND_DISPLAY" --kind mark --album "$PHOTOS_ALBUM" --open; then
      step "Click 'Add Shortcut' for 'Mark for $BRAND_DISPLAY' in the Shortcuts window that just opened."
    else
      warn "could not build the Mark shortcut here; on the phone use Share → Add to Album → $PHOTOS_ALBUM instead"
      SKIPPED+=("Mark shortcut: longform shortcut --profile $PROFILE --kind mark --album '$PHOTOS_ALBUM' --open (or Share → Add to Album on the phone)")
    fi
  else
    note "the Mark shortcut needs the longform binary and the Mac Shortcuts app; until then use Share → Add to Album → $PHOTOS_ALBUM on the phone"
  fi
  pause "Album made and 'Mark for $BRAND_DISPLAY' added (or later)? Enter goes on to the inbox shortcut"
fi
say "The inbox Shortcut can be built here: the Mac's Shortcuts app imports it after one click"
say "and iCloud syncs it to the phone. Building it by hand on the phone also works."
if BIN=$(find_bin) && command -v shortcuts >/dev/null 2>&1; then
  if "$BIN" shortcut --profile "$PROFILE" --brand "$BRAND_DISPLAY" --open; then
    step "Click 'Add Shortcut' in the Shortcuts window that just opened. It appears on the iPhone within a minute (Shortcuts → iCloud sync must be on)."
  else
    warn "could not build the shortcut here; build it by hand instead:"
    print_shortcut_recipe
  fi
else
  print_shortcut_recipe
fi
pause "Shortcut added (or you'll do it later)?"

# ── 10 ─────────────────────────────────────────────────────────────────────
stage "Write the profile"
ask_default TIMEZONE "Timezone:" "$(pdefault .timezone America/Los_Angeles)"
ask_default SLOTS "Posting slots, local HH:MM comma-separated:" "$(pdefault '.slots_local | join(",")' "09:00,12:00,15:00,18:00,21:00")"
ask_default BACKLOG_DAYS "Backlog days before held clips expire:" "$(pdefault .backlog_days 25)"
say "Cadence: posts per day per platform (0 disables a platform)."
for k in youtube instagram linkedin tiktok facebook; do
  case $k in youtube|tiktok) d=2;; *) d=1;; esac
  while :; do
    ask_default "CAD_$k" "  $k:" "$(pdefault ".cadence.$k" "$d")"
    v="CAD_$k"; [[ "${!v}" =~ ^[0-9]+$ ]] && break
    warn "whole number of posts per day, please"
  done
done
ask_default STAB "Stabilize with vidstab (true/false):" "$(pdefault .stabilize.enabled true)"
[[ "$STAB" == false ]] || STAB=true
ask_default CENSOR_MODE "Censor mode, beep or mute:" "$(pdefault .censor.mode beep)"
[[ "$CENSOR_MODE" == mute ]] || CENSOR_MODE=beep
ask_default CENSOR_EXTRA "Extra censored words, comma-separated (blank = none):" "$(pdefault '.censor.extra | join(",")' "")"
ask_default WHISPER_MODEL "whisper ggml model path (blank = default):" "$(pdefault .transcribe.model "")"
ask_default COPY_STYLE "Copy style (evc, bjj-question, or plain):" "$(pdefault .copy.style "evc")"
ask_default VOICE_CORPUS "Voice corpus path (blank = none):" "$(pdefault .copy.voice_corpus "$CONFIG_ROOT/voice/$PROFILE.json")"
ask_default BOILERPLATE "Caption boilerplate appended on Instagram/TikTok (blank = none):" "$(pdefault .copy.boilerplate "")"
ask_default LM_NEWSLETTER "Lead magnet URL 'newsletter' (blank = none):" "$(pdefault .cta.lead_magnets.newsletter "")"
ask_default LM_DISCORD "Lead magnet URL 'discord' (blank = none):" "$(pdefault .cta.lead_magnets.discord "")"
ask_default DM_KEYWORD "Comment-to-DM keyword for instagram/tiktok (blank = none):" "$(pdefault .cta.comment_to_dm.instagram "")"
ask_statics
if [[ "$STATICS_ENGINE" == templates ]]; then mkdir -p "$(expand_tilde "$TEMPLATES_DIR")"; fi

# The profile is rebuilt on top of the existing file: every field this wizard
# asks about is set from the answers, and anything else (hand-set values,
# extra, brand tokens of an unused engine, more cadence or channel keys) is kept.
# The ACCT_*, BTAG_*, BCHAN_* and CAD_* values are set by ask_default via printf -v.
# The inbox is stored with a literal ~ on purpose: the Go binary expands it, so the
# profile stays portable across users.
OLD_PROFILE=/dev/null
[[ -f "$PROFILE_FILE" ]] && OLD_PROFILE="$PROFILE_FILE"
# shellcheck disable=SC2154,SC2088
jq -n --slurpfile old "$OLD_PROFILE" \
  --arg name "$PROFILE" --arg display "$BRAND_DISPLAY" --arg site "$BRAND_SITE" \
  --arg inbox "~/Library/Mobile Documents/iCloud~is~workflow~my~workflows/Documents/longform-inbox/$PROFILE" \
  --arg orientation "$ORIENTATION" --argjson stitch "$STITCH" --argjson stitch_win "${STITCH_WINDOW:-90}" \
  --argjson stab "$STAB" --arg censor_mode "$CENSOR_MODE" --arg censor_extra "$CENSOR_EXTRA" \
  --arg whisper "$WHISPER_MODEL" \
  --arg template "$TEMPLATE_ID" --argjson strip "$STRIP_OVERLAY" \
  --arg smodel "$SHORTS_MODEL" --arg sprompt "$SHORTS_PROMPT" --argjson filler "$REMOVE_FILLER" \
  --arg a_youtube "$ACCT_youtube" --arg a_instagram "$ACCT_instagram" --arg a_facebook "$ACCT_facebook" \
  --arg a_linkedin_page "$ACCT_linkedin_page" --arg a_linkedin_profile "$ACCT_linkedin_profile" --arg a_tiktok "$ACCT_tiktok" \
  --arg s_instagram "${SUB_instagram:-}" --arg s_facebook "${SUB_facebook:-}" --arg s_linkedin_page "${SUB_linkedin_page:-}" --arg s_linkedin_profile "${SUB_linkedin_profile:-}" \
  --argjson c_youtube "${CAD_youtube:-0}" --argjson c_instagram "${CAD_instagram:-0}" --argjson c_linkedin "${CAD_linkedin:-0}" \
  --argjson c_tiktok "${CAD_tiktok:-0}" --argjson c_facebook "${CAD_facebook:-0}" \
  --arg slots "$SLOTS" --arg tz "$TIMEZONE" --argjson backlog "${BACKLOG_DAYS:-25}" \
  --arg lm_news "$LM_NEWSLETTER" --arg lm_discord "$LM_DISCORD" --arg dm "$DM_KEYWORD" \
  --arg style "$COPY_STYLE" --arg corpus "$VOICE_CORPUS" --arg boiler "$BOILERPLATE" \
  --arg bc_instagram "$BCHAN_instagram" --arg bc_linkedin "$BCHAN_linkedin" --arg bc_facebook "$BCHAN_facebook" --arg bc_threads "$BCHAN_threads" \
  --arg bt_quote "$BTAG_video_quote" --arg bt_carousel "$BTAG_video_carousel" --arg bt_still "$BTAG_video_still" --arg bt_frame "$BTAG_video_frame_carousel" \
  --arg templates "$TEMPLATES_DIR" --arg slack "$SLACK_CHANNEL" \
  --arg album "$PHOTOS_ALBUM" --arg osxphotos "${OSXPHOTOS:-}" --argjson dlmissing "$PHOTOS_DL_MISSING" --arg plibrary "$PHOTOS_LIBRARY" \
  --arg engine "$STATICS_ENGINE" --arg formats "$STATICS_FORMATS" --arg carousel "$CAROUSEL_DIR" \
  --arg refdir "$REFERENCE_DIR" --argjson tokens "$BRAND_TOKENS" --argjson ftags "$FORMAT_TAGS" \
  --arg static_cta "$STATIC_CTA" --arg cta_script "$CTA_SCRIPT" \
  'def csv: split(",") | map(gsub("^\\s+|\\s+$";"")) | map(select(length > 0));
   def dflt(p; v): if getpath(p) == null then setpath(p; v) else . end;
   def setor(p; v): if v == "" then delpaths([p]) else setpath(p; v) end;
   def nonempty: with_entries(select(.value != ""));
   ($old[0] // {})
   | .name = $name
   | .brand.display = $display | .brand.site = $site
   | (if $engine == "custom-html" then .brand += $tokens else . end)
   | .inbox = $inbox
   | .photos.enabled = ($album != "") | .photos.album = $album | .photos.download_missing = $dlmissing
   | (if $osxphotos == "" then . else .photos.osxphotos = $osxphotos end)
   | setor(["photos","library"]; $plibrary)
   | .orientation = $orientation
   | .stitch.enabled = $stitch | .stitch.session_window_min = $stitch_win
   | .stabilize.enabled = $stab
   | dflt(["stabilize","shakiness"]; 5) | dflt(["stabilize","smoothing"]; 15) | dflt(["stabilize","zoom"]; 3)
   | dflt(["censor","enabled"]; true) | .censor.mode = $censor_mode | .censor.extra = ($censor_extra | csv)
   | .transcribe.model = $whisper | dflt(["transcribe","language"]; "en") | dflt(["transcribe","threads"]; 0)
   | .opusclip.template_id = $template
   | .opusclip.strip_overlay = $strip
   | .opusclip.shorts.model = $smodel | .opusclip.shorts.remove_filler = $filler
   | dflt(["opusclip","shorts","durations"]; [30, 60, 90]) | dflt(["opusclip","shorts","aspect"]; "portrait")
   | setor(["opusclip","shorts","prompt"]; $sprompt)
   | dflt(["opusclip","full","skip_curate"]; true) | .opusclip.full.aspect = $orientation
   | .opusclip.accounts = ({ youtube: $a_youtube, instagram: $a_instagram, facebook: $a_facebook, linkedin_page: $a_linkedin_page, linkedin_profile: $a_linkedin_profile, tiktok: $a_tiktok } | nonempty)
   | .opusclip.sub_accounts = ({ instagram: $s_instagram, facebook: $s_facebook, linkedin_page: $s_linkedin_page, linkedin_profile: $s_linkedin_profile } | nonempty)
   | .cadence = ((.cadence // {}) + { youtube: $c_youtube, instagram: $c_instagram, linkedin: $c_linkedin, tiktok: $c_tiktok, facebook: $c_facebook })
   | .slots_local = ($slots | csv)
   | .timezone = $tz
   | .backlog_days = $backlog
   | .cta.lead_magnets = ((.cta.lead_magnets // {}) + { newsletter: $lm_news, discord: $lm_discord } | nonempty)
   | .cta.comment_to_dm = ((.cta.comment_to_dm // {}) + { instagram: $dm, tiktok: $dm } | nonempty)
   | dflt(["cta","utm_source_by_platform"]; true)
   | setor(["cta","static_cta"]; $static_cta)
   | (if $static_cta == "" then . else setor(["cta","cta_script"]; $cta_script) end)
   | .copy.style = $style | setor(["copy","voice_corpus"]; $corpus) | setor(["copy","boilerplate"]; $boiler)
   | .buffer.channels = ((.buffer.channels // {}) + { instagram: $bc_instagram, linkedin: $bc_linkedin, facebook: $bc_facebook, threads: $bc_threads } | nonempty)
   | .buffer.tags = ((.buffer.tags // {}) + { video_quote: $bt_quote, video_carousel: $bt_carousel, video_still: $bt_still, video_frame_carousel: $bt_frame } | nonempty)
   | (if $ftags == {} then delpaths([["buffer","format_tags"]]) else .buffer.format_tags = $ftags end)
   | .statics.engine = $engine
   | .statics.formats = ($formats | csv)
   | (if $engine == "templates" then .statics.templates_dir = $templates else . end)
   | (if $engine == "newsletter-carousel" then .statics.carousel_dir = $carousel else . end)
   | (if $engine == "custom-html" then setor(["statics","reference_dir"]; $refdir) else . end)
   | dflt(["notify","macos"]; true) | setor(["notify","slack_channel"]; $slack)
  ' > "$PROFILE_FILE.tmp" && mv "$PROFILE_FILE.tmp" "$PROFILE_FILE"
printf '  %s✓ wrote%s %s\n' "$GREEN" "$RESET" "$PROFILE_FILE"
if [[ "$STATICS_ENGINE" == templates ]]; then
  note "templates for statics go in $TEMPLATES_DIR (see docs/templates.md)"
fi
pause

# ── 11 ─────────────────────────────────────────────────────────────────────
stage "Install the launchd watcher"
say "A LaunchAgent watches every profile inbox and ticks every 10 minutes."
if launchd_install; then
  note "logs: $LOG_DIR/watch.log"
  if [[ -n "$PHOTOS_ALBUM" ]] && BIN=$(find_bin); then
    photos_access_check
  fi
else
  SKIPPED+=("launchd: run 'make launchd-install' after 'make install'")
fi
pause

# ── 12 ─────────────────────────────────────────────────────────────────────
stage "Dry run"
FIXTURE="$CONFIG_ROOT/fixtures/sample-30s.mp4"
say "Generates a 30-second test video and stages it as a job (no OpusClip credits are spent by 'stage')."
if make_fixture "$FIXTURE" && BIN=$(find_bin); then
  load_env
  if "$BIN" stage --profile "$PROFILE" --file "$FIXTURE"; then
    "$BIN" status
  else
    warn "longform stage failed; see output above"
    SKIPPED+=("dry run: longform stage --profile $PROFILE --file $FIXTURE")
  fi
else
  SKIPPED+=("dry run: make fixture && longform stage --profile $PROFILE --file $FIXTURE")
fi
if [[ -n "$PHOTOS_ALBUM" ]]; then
  note "Next: record a real video, Share → 'Mark for $BRAND_DISPLAY', then watch 'longform status'."
else
  note "Next: record a real video, Share → your Shortcut, then watch 'longform status'."
fi

finish
}

main() {
  case "${1:-}" in
    launchd-install)   launchd_install ;;
    launchd-uninstall) launchd_uninstall ;;
    fixture)           make_fixture "${2:-$PLUGIN_ROOT/fixtures/sample-30s.mp4}" ;;
    -h|--help)         sed -n '/^# Usage:/,/^# ───/p' "${BASH_SOURCE[0]}" ;;
    *)                 run_wizard "$@" ;;
  esac
}

main "$@"; exit
